typedef float rational_t;
typedef unsigned int u_int;

class entity_id;
class entity;
class entity_link_ifc
{
public:
  void set_parent( entity* );
};

enum entity_flavor_t
{
  ENTITY_CAMERA,
  ENTITY_ENTITY,
  ENTITY_MARKER,
  ENTITY_MIC,
  ENTITY_LIGHT_SOURCE
};

class entity
{
  char released_layout[0x204];
public:
  entity( const entity_id&, entity_flavor_t );
  entity_link_ifc* link_ifc();
};

class color
{
public:
  rational_t r, g, b, a;
  color( const color& c ) : r(c.r), g(c.g), b(c.b), a(c.a) {}
};

enum light_flavor_t
{
  LIGHT_FLAVOR_POINT,
  LIGHT_FLAVOR_SPOT,
  LIGHT_FLAVOR_DIRECTIONAL,
  LIGHT_FLAVOR_PARALLELPOINT,
  NUM_LIGHT_FLAVORS
};

class light_properties 
{
protected:
  light_flavor_t flavor;
  color          diffuse_color;
  color          additive_color;
  rational_t     near_range;
  rational_t     cutoff_range;
  rational_t     recip_cutoff_minus_near;
  u_int lightcat;
  unsigned flags;
  friend class light_source;
};

class light_source : public entity
{
public:
  light_source( const light_properties& _properties,
                entity* parent,
                const entity_id& _id );
private:
  light_properties* properties;
};

#define NEW new
#define NULL 0

light_source::light_source( const light_properties& _properties,
                            entity* _parent,
                            const entity_id& _id )
  :   entity( _id, ENTITY_LIGHT_SOURCE )
{
  properties = NEW light_properties( _properties );
  if (_parent != NULL)
    link_ifc()->set_parent( _parent );
}
